using FacciStats;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace FacciStats;
[ApiController, Route("api/v1/personajes")] public class PersonajesController(AppDbContext db, ApiService s) : ControllerBase { [HttpGet] public async Task<object> Listar() => new { data=(await db.Personajes.AsNoTracking().OrderBy(x=>x.Id).ToListAsync()).Select(s.Map) }; [HttpGet("{id:int}")] public async Task<IActionResult> Uno(int id) => (await s.Personaje(id)) is { } x ? Ok(x) : NotFound(); [HttpPost] public async Task<IActionResult> Crear(PersonajeRequest r) { var x=new Personaje { Nombre=r.Nombre.Trim(),Faccion=r.Faccion.Trim(),EstaMuerto=r.EstaMuerto,BiografiaSecreta=string.IsNullOrWhiteSpace(r.BiografiaSecreta)?null:HttpContext.RequestServices.GetRequiredService<CifradoService>().Cifrar(r.BiografiaSecreta) }; db.Add(x); await db.SaveChangesAsync(); return CreatedAtAction(nameof(Uno),new {id=x.Id},s.Map(x)); } [HttpPut("{id:int}")] public async Task<IActionResult> Editar(int id, PersonajeRequest r) { var x=await db.Personajes.FindAsync(id); if(x is null)return NotFound(); x.Nombre=r.Nombre.Trim();x.Faccion=r.Faccion.Trim();x.EstaMuerto=r.EstaMuerto;x.BiografiaSecreta=string.IsNullOrWhiteSpace(r.BiografiaSecreta)?null:HttpContext.RequestServices.GetRequiredService<CifradoService>().Cifrar(r.BiografiaSecreta);await db.SaveChangesAsync();return Ok(s.Map(x)); } [HttpDelete("{id:int}")] public async Task<IActionResult> Eliminar(int id) { var x=await db.Personajes.Include(x=>x.Cartas).FirstOrDefaultAsync(x=>x.Id==id); if(x is null)return NotFound();if(x.Cartas.Count>0)return BadRequest(new { mensaje="El personaje tiene cartas asociadas."});db.Remove(x);await db.SaveChangesAsync();return NoContent(); } }
[ApiController, Route("api/v1/cartas")] public class CartasController(AppDbContext db) : ControllerBase { [HttpGet] public async Task<object> Listar()=>new {data=await db.Cartas.Include(x=>x.Personaje).AsNoTracking().Select(x=>new{x.Id,x.Nombre,x.Poder,x.PersonajeId,personaje=x.Personaje!.Nombre}).ToListAsync()}; [HttpPost] public async Task<IActionResult> Crear(CartaRequest r){if(!await db.Personajes.AnyAsync(x=>x.Id==r.PersonajeId))return BadRequest(new{mensaje="Personaje inexistente."});var x=new Carta{PersonajeId=r.PersonajeId,Nombre=r.Nombre.Trim(),Poder=r.Poder};db.Add(x);await db.SaveChangesAsync();return Created($"api/v1/cartas/{x.Id}",x);} [HttpDelete("{id:int}")] public async Task<IActionResult> Eliminar(int id){var x=await db.Cartas.FindAsync(id);if(x is null)return NotFound();db.Remove(x);await db.SaveChangesAsync();return NoContent();} }
[ApiController, Route("api/v1/eventos")] public class EventosController(AppDbContext db) : ControllerBase { [HttpGet] public async Task<object> Listar()=>new{data=await db.Eventos.AsNoTracking().OrderByDescending(x=>x.Fecha).ToListAsync()}; [HttpPost] public async Task<IActionResult> Crear(EventoRequest r){var x=new Evento{Nombre=r.Nombre.Trim(),Fecha=r.Fecha,FaccionGanadora=r.FaccionGanadora.Trim()};db.Add(x);await db.SaveChangesAsync();return Created($"api/v1/eventos/{x.Id}",x);} [HttpDelete("{id:int}")]public async Task<IActionResult> Eliminar(int id){var x=await db.Eventos.FindAsync(id);if(x is null)return NotFound();db.Remove(x);await db.SaveChangesAsync();return NoContent();} }
[ApiController, Route("api/v1/usuarios")] public class UsuariosController(AppDbContext db, ApiService s, CifradoService c) : ControllerBase { [HttpGet] public async Task<object> Listar()=>new{data=(await db.Usuarios.AsNoTracking().ToListAsync()).Select(x=>new{x.Id,x.Nombre,x.Email,Telefono=x.Telefono is null?null:c.Descifrar(x.Telefono)})}; [HttpPost] public async Task<IActionResult> Crear(UsuarioRequest r){if(await db.Usuarios.AnyAsync(x=>x.Email==r.Email.Trim().ToLower()))return Conflict(new{mensaje="El correo ya existe."});var u=await s.CrearUsuario(r);return Created($"api/v1/usuarios/{u.Id}",new{u.Id,u.Nombre,u.Email});} }
[ApiController, Route("api/v1/facciones")] public class FaccionesController(AppDbContext db, ApiService s) : ControllerBase { [HttpGet] public async Task<object> Lista()=>new{data=(await s.Estadisticas()).Select(x=>new{x.Faccion,x.Personajes})}; [HttpGet("estadisticas")] public async Task<object> Stats(string? ordenarPor=null,string direccion="asc"){var x=await s.Estadisticas();if(ordenarPor=="poderPromedio")x=direccion=="desc"?x.OrderByDescending(a=>a.PoderPromedio).ToList():x.OrderBy(a=>a.PoderPromedio).ToList();return new{data=x};} [HttpGet("{nombre}/estadisticas")] public async Task<IActionResult> Uno(string nombre){var x=(await s.Estadisticas()).FirstOrDefault(x=>string.Equals(x.Faccion,nombre,StringComparison.OrdinalIgnoreCase));return x is null?NotFound():Ok(new{data=x});} [HttpGet("{nombre}/personajes")] public async Task<IActionResult> Personajes(string nombre,string estado="todos",int pagina=1,int tamano=10){if(pagina<1||tamano is<1 or>50)return BadRequest(new{mensaje="Paginación inválida."});var q=db.Personajes.AsNoTracking().Where(x=>x.Faccion==nombre);if(estado=="vivos")q=q.Where(x=>!x.EstaMuerto);else if(estado=="muertos")q=q.Where(x=>x.EstaMuerto);else if(estado!="todos")return BadRequest(new{mensaje="Estado inválido."});var total=await q.CountAsync();return Ok(new{data=await q.Skip((pagina-1)*tamano).Take(tamano).ToListAsync(),meta=new{pagina,tamano,total}});} [HttpGet("{nombre}/cartas")] public async Task<object> Cartas(string nombre,int? poderMinimo=null,string orden="asc"){var q=db.Cartas.Include(x=>x.Personaje).Where(x=>x.Personaje!.Faccion==nombre);if(poderMinimo.HasValue)q=q.Where(x=>x.Poder>=poderMinimo);return new{data=await(orden=="desc"?q.OrderByDescending(x=>x.Poder):q.OrderBy(x=>x.Poder)).Select(x=>new{x.Id,x.Nombre,x.Poder,personaje=x.Personaje!.Nombre}).ToListAsync()};} [HttpGet("{nombre}/eventos-ganados")]public async Task<object> Eventos(string nombre,DateTime? desde=null,DateTime? hasta=null){var q=db.Eventos.Where(x=>x.FaccionGanadora==nombre);if(desde.HasValue)q=q.Where(x=>x.Fecha>=desde);if(hasta.HasValue)q=q.Where(x=>x.Fecha<=hasta);return new{data=await q.OrderByDescending(x=>x.Fecha).ToListAsync()};} [HttpGet("ranking")]public async Task<IActionResult> Ranking(string criterio="personajes",int top=10){if(top is<1 or>20)return BadRequest();var x=await s.Estadisticas();var o=criterio switch{"poderPromedio"=>x.OrderByDescending(a=>a.PoderPromedio),"eventosGanados"=>x.OrderByDescending(a=>a.EventosGanados),"personajes"=>x.OrderByDescending(a=>a.Personajes),_=>null};return o is null?BadRequest(new{mensaje="Criterio inválido."}):Ok(new{data=o.Take(top).Select((a,i)=>new{posicion=i+1,a.Faccion,valor=criterio=="personajes"?a.Personajes:criterio=="eventosGanados"?a.EventosGanados:a.PoderPromedio})});} [HttpGet("comparar")]public async Task<IActionResult> Comparar(string faccionA,string faccionB){if(string.Equals(faccionA,faccionB,StringComparison.OrdinalIgnoreCase))return BadRequest();var x=await s.Estadisticas();var a=x.FirstOrDefault(x=>x.Faccion==faccionA);var b=x.FirstOrDefault(x=>x.Faccion==faccionB);return a is null||b is null?NotFound():Ok(new{faccionA=a,faccionB=b,diferencias=new{personajes=a.Personajes-b.Personajes,eventosGanados=a.EventosGanados-b.EventosGanados}});} }
[ApiController, Route("api/v1/estadisticas")] public class EstadisticasController(AppDbContext db) : ControllerBase { [HttpGet("generales")] public async Task<object> Generales()=>new{data=new{facciones=await db.Personajes.Select(x=>x.Faccion).Distinct().CountAsync(),personajes=await db.Personajes.CountAsync(),vivos=await db.Personajes.CountAsync(x=>!x.EstaMuerto),muertos=await db.Personajes.CountAsync(x=>x.EstaMuerto),cartas=await db.Cartas.CountAsync(),eventos=await db.Eventos.CountAsync()}}; }
